import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final BigInteger MOD = new BigInteger("998244353");
    static void errorMessage() {
        System.out.println(-1);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int testCount = 1;
        // testCount = Integer.parseInt(st.nextToken());
        while (testCount-- > 0) {
            st = new StringTokenizer(br.readLine());
            long n = Long.parseLong(st.nextToken());
            long m = Long.parseLong(st.nextToken());
            st = new StringTokenizer(br.readLine());
            long l = Long.parseLong(st.nextToken());
            long r = Long.parseLong(st.nextToken());
            long diff = r - l;
            long evenPart = diff / 2 + 1;
            long oddPart = (diff + 1) / 2;
            if ((n * m) % 2 == 1) {
                BigInteger base = BigInteger.valueOf(diff + 1);
                BigInteger res = base.modPow(BigInteger.valueOf(n * m), MOD);
                out.println(res);
            } else {
                BigInteger p1 = BigInteger.valueOf(evenPart + oddPart).modPow(BigInteger.valueOf(n * m), MOD);
                BigInteger p2 = BigInteger.valueOf(evenPart - oddPart).modPow(BigInteger.valueOf(n * m), MOD);
                BigInteger total = p1.add(p2);
                BigInteger invTwo = BigInteger.valueOf(2).modInverse(MOD);
                BigInteger answer = total.multiply(invTwo).mod(MOD);
                out.println(answer);
            }
        }
        out.flush();
    }
}
